U1.M('q01', L145, 34, 'The valency of an element in Group VI is …', ['6', '2', '1', '4'], 'B',
     ['Step 1: Group VI has 6 valence electrons.', 'Step 2: it needs 8 − 6 = 2 more to complete the octet.', 'Step 3: so its valency is 2 (e.g. H₂O, H₂S).'],
     'Groups V–VII: valency = 8 − group number.', [('Valency of Group VII?', '1.'), ('Valency of Group IV?', '4.')])
