# ====================================================================================== Unit 5 · 5.1.4
U5 = Unit('chem10-u5')
L514 = '5.1.4 Enthalpy of a chemical reaction'

ENTH = [
    U5.T('c01', '5.1.4 Enthalpy and ΔH, step by step', 157,
         'Every substance stores energy in its bonds. The **heat content** of a substance at constant pressure is called its **enthalpy, H**. We cannot measure H itself, but we can measure the **change**, ΔH (“delta H”), during a reaction.',
         '$$\\Delta H = H_{\\text{products}} - H_{\\text{reactants}} = H_P - H_R$$',
         '**Step 1 — Bonds in the reactants are broken.** This never happens by itself: energy must be **supplied** (absorbed), so this stage is endothermic.',
         '**Step 2 — New bonds in the products are formed.** This happens by itself and energy is **released**, so this stage is exothermic.',
         '**Step 3 — Compare the two amounts:**',
         '$$\\Delta H = \\sum(\\text{energy to break bonds}) - \\sum(\\text{energy released forming bonds})$$',
         'If more energy is released than absorbed, ΔH is **negative** (exothermic, H_P < H_R). If more is absorbed, ΔH is **positive** (endothermic, H_P > H_R).',
         '**Unit:** kilojoules per mole, **kJ/mol** — per mole of reaction as written in the equation.',
         '**Activity 5.5 explained:** adding quicklime (CaO) to water makes the beaker hot. Heat flows **from the beaker to your hand**: the reaction CaO + H₂O → Ca(OH)₂ releases energy, so ΔH is negative.'),
    U5.ST('s01', 'Model: break bonds, then make bonds (H₂ + Cl₂ → 2HCl)', 158, 'co_bonds',
          [('**Break:** H–H (436 kJ) and Cl–Cl (243 kJ) need 679 kJ in total — the energy goes **up** to separate atoms.', 'break'),
           ('**Make:** two H–Cl bonds form (2 × 432 = 864 kJ) — energy comes **out**.', 'make'),
           ('**Net:** ΔH = 679 − 864 = **−185 kJ** per mole of reaction: the products are lower, the reaction is exothermic.', 'net')]),
    U5.TB('t01', 'Bond energies (kJ/mol) — textbook Table 5.1 plus values used below', 157,
          ['Bond', 'Energy', 'Bond', 'Energy'],
          [['H–H', '436', 'C–H', '413'], ['Cl–Cl', '243', 'C–C', '348'], ['H–Cl', '432', 'C=C', '614'], ['H–Br', '366', 'C≡C', '839'], ['H–F', '565', 'C–O', '360'],
           ['O=O', '498', 'C=O (in CO₂)', '805'], ['N≡N', '945', 'O–H', '463'], ['N–H', '391', '', '']],
          'Corrections to Table 5.1: the 945 kJ bond is the nitrogen **triple** bond N≡N, and the 839 kJ carbon bond is the **triple** bond C≡C (two lines in the table print “N=N” and a second “C=C”). Triple > double > single.'),
    U5.TB('t02', 'Exothermic and endothermic in terms of enthalpy', 158,
          ['', 'Exothermic', 'Endothermic'],
          [['Bond energy balance', 'released (making) > absorbed (breaking)', 'absorbed (breaking) > released (making)'],
           ['H_P compared with H_R', 'H_P < H_R', 'H_P > H_R'], ['Sign of ΔH', 'negative (−)', 'positive (+)'],
           ['Surroundings', 'get warmer', 'get colder (or must be heated)'], ['Example', 'CaO + H₂O → Ca(OH)₂', 'CaCO₃ → CaO + CO₂']]),
    U5.WK('w01', 'Worked example: ΔH from bond energies (hydrogen chloride)', 158,
          'Use bond energies to find ΔH for H₂(g) + Cl₂(g) → 2HCl(g). (H–H 436, Cl–Cl 243, H–Cl 432 kJ/mol)',
          ['Bonds broken: 1 H–H + 1 Cl–Cl = 436 + 243 = 679 kJ (absorbed).', 'Bonds formed: 2 H–Cl = 2 × 432 = 864 kJ (released).',
           r'\(\Delta H = 679 - 864 = -185\ \text{kJ}\)', 'Negative → exothermic.'],
          'ΔH = −185 kJ/mol (exothermic)'),
    U5.WK('w02', 'Worked example: the Haber reaction', 158,
          'Find ΔH for N₂(g) + 3H₂(g) → 2NH₃(g). (N≡N 945, H–H 436, N–H 391 kJ/mol)',
          ['Broken: 1 N≡N + 3 H–H = 945 + 3 × 436 = 945 + 1308 = 2253 kJ.', 'Formed: each NH₃ has 3 N–H, so 2NH₃ has 6 N–H = 6 × 391 = 2346 kJ.',
           r'\(\Delta H = 2253 - 2346 = -93\ \text{kJ}\)', 'Exothermic. (The measured value is −92 kJ — very close.)'],
          'ΔH ≈ −93 kJ/mol'),
    U5.WK('w03', 'Worked example: burning methane from bond energies', 158,
          'Estimate ΔH for CH₄(g) + 2O₂(g) → CO₂(g) + 2H₂O(g). (C–H 413, O=O 498, C=O 805, O–H 463 kJ/mol)',
          ['Broken: 4 C–H + 2 O=O = 4(413) + 2(498) = 1652 + 996 = 2648 kJ.', 'Formed: 2 C=O + 4 O–H = 2(805) + 4(463) = 1610 + 1852 = 3462 kJ.',
           r'\(\Delta H = 2648 - 3462 = -814\ \text{kJ}\)',
           'Bond energies are **averages**, and here the water is a gas; that is why the answer differs from the measured −890 kJ (with liquid water).'],
          'ΔH ≈ −814 kJ/mol'),
    U5.WK('w04', 'Worked example: using H_P − H_R', 158,
          'For a reaction the total enthalpy of the reactants is 250 kJ and of the products 120 kJ. Find ΔH and say whether the reaction is exo- or endothermic. What is ΔH of the reverse reaction?',
          [r'\(\Delta H = H_P - H_R = 120 - 250 = -130\ \text{kJ}\)', 'Negative → **exothermic**.', 'Reverse reaction: same size, opposite sign → **+130 kJ** (endothermic).'],
          '−130 kJ (exothermic); reverse +130 kJ'),
    U5.CK('k01', 158, 'Breaking a chemical bond …', ['releases energy', 'absorbs energy', 'needs no energy', 'always makes the surroundings hot'], 'B',
          'Energy must be supplied to pull bonded atoms apart. Energy is released when bonds form.'),
    U5.CK('k02', 158, 'If H_P is greater than H_R, the reaction is …', ['exothermic, ΔH negative', 'endothermic, ΔH positive', 'neither', 'explosive'], 'B',
          'ΔH = H_P − H_R > 0 → energy was taken in → endothermic.'),
    U5.RM('r01', 'Tips and common mistakes', 158,
          'ΔH = (bonds broken) − (bonds formed) — reactant bonds first. Do not reverse it.',
          'Count every bond: 2NH₃ has 6 N–H bonds; CO₂ has 2 C=O bonds; 2O₂ has 2 O=O bonds.',
          'Exothermic → negative ΔH, even though “heat is given out”.'),
]
